class EventTicket4{protected double balanceDue;EventTicket4(double p){balanceDue=p;}void printTicket(){System.out.print("Standard | Balance: "+balanceDue+" | ");}}
class WorkshopTicket4 extends EventTicket4{String track;WorkshopTicket4(double p,String t){super(p);track=t;}@Override void printTicket(){System.out.print("Workshop | Track: "+track+" | Balance: "+balanceDue+" | ");}}
public class Problem4{static String batchPrint(EventTicket4[] a){StringBuilder s=new StringBuilder();for(EventTicket4 t:a){if(t==null)continue;t.printTicket();if(t instanceof WorkshopTicket4){WorkshopTicket4 w=(WorkshopTicket4)t;s.append("[Track via downcast: ").append(w.track).append("] | ");} }return s.toString();}public static void main(String[]x){System.out.println(batchPrint(new EventTicket4[]{new EventTicket4(500),new WorkshopTicket4(1200,"AI/ML")}));}}
